window.STORY_ID = {"inkVersion":21,"root":[[{"->":"prolog1"},["done",{"#n":"g-0"}],null],"done",{"prolog1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Kamu terbangun di ujung lorong gelap yang bau dan lembap. Segalanya terasa kotor, penuh puing-puing dan pecahan kaca. Beberapa pintu rusak dan tergantung miring, membuat bayangan-bayangan aneh di bawah cahaya redup.","\n","^Di dinding ada coretan-coretan — seperti pesan atau peringatan, tetapi hampir semuanya susah untuk dibaca.","\n","^Lalu, kamu melihat tanganmu. Keduanya dibalut perban kotor. Tapi kamu nggak merasakan ada rasa sakit sama sekali.","\n","^Disaat kamu mencoba mengingat apa yang terjadi, kepalamu terasa kosong. Kamu nggak ingat apa-apa. Nggak tahu ini di mana, kenapa kamu di sini, atau harus ngapain.","\n","end",null],"prolog2":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","^Setelah berjalan ke depan dengan kebingungan sesaat, kini di depanmu terlihat empat pintu — masing-masing menampilkan kesannya tersendiri.","\n","^Pintu paling kiri tertutup rapat. Engselnya berkarat, tapi gagangnya terlihat agak bersih dari debu, seperti baru saja dipakai. Pintu kedua di kiri tampak terbuka lebar dan setengah rusak.","\n","^Kemudian, pintu pertama di sisi kanan berayun pelan, berderit kecil meski tak ada angin sedikit pun — seperti ada yang meniupnya. Pintu kedua lebih tenang dan normal, tapi dari celahnya kamu bisa lihat bayangan samar terletak di atas meja.","\n","^Lorong terus berlanjut, tapi suasananya makin tidak nyaman. Lampu-lampu berkedip tak menentu, dan entah dari mana, kamu sempat dengar suara gemerisik... lalu hening total.","\n",{"->":"opening"},null],"opening":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","^Kau berdiri di tengah lorong. Empat pintu mengapitmu — dua di kiri, dua di kanan — dan di depan, lorong terus berlanjut ke dalam kegelapan yang semakin pekat.","\n","^Apa yang akan kau lakukan?","\n","ev","str","^Mengecek pintu pertama di kiri","/str",{"VAR?":"f_d1"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Mengecek pintu kedua di kiri","/str",{"VAR?":"f_d2"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Mengecek pintu pertama di kanan","/str",{"VAR?":"f_d3"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Mengecek pintu kedua di kanan","/str",{"VAR?":"f_d4"},"!","/ev",{"*":".^.c-3","flg":21},"ev","str","^Terus maju meski ragu.","/str","/ev",{"*":".^.c-4","flg":4},{"c-0":["\n","ev",true,"/ev",{"VAR=":"f_d1","re":true},{"->":"d1_hub"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"f_d2","re":true},{"->":"d2_hub"},{"#f":5}],"c-2":["\n","ev",true,"/ev",{"VAR=":"f_d3","re":true},{"->":"d3_hub"},{"#f":5}],"c-3":["\n","ev",true,"/ev",{"VAR=":"f_d4","re":true},{"->":"d4_hub"},{"#f":5}],"c-4":["^ ",{"->":"d5_1"},"\n",null]}],null],"d1_hub":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Kau mendekati pintu paling kiri. Tertutup rapat. Engselnya berkarat — tapi gagang pintunya bersih. Terlalu bersih untuk tempat sekotor ini.","\n","^Seperti baru saja digenggam. Oleh seseorang. Atau sesuatu.","\n","^Kayunya dingin saat kau mendekat.","\n","ev","str","^Tempelkan telinga ke pintu, dengarkan dulu","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Dorong perlahan, intip lewat celah","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Buka lebar-lebar sekaligus","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"d1_a"},"\n",null],"c-1":["^ ",{"->":"d1_b"},"\n",null],"c-2":["^ ",{"->":"d1_c"},"\n",null]}],null],"d1_a":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Kau menempelkan telinga ke permukaan kayu yang dingin dan menahan napas.","\n","^Hening.","\n","^Kau mencoba mendengar sesuatu — apa pun — dari balik pintu. Tidak ada. Hanya dengung darah di telingamu sendiri dan... tunggu. Apakah itu detak?","\n","^Detak jantungmu sendiri, tentu saja. Pasti.","\n","^Tidak ada suara lain. Ruangan di baliknya sepertinya kosong.","\n",{"->":"d1_a2"},null],"d1_a2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Pintu itu diam. Keputusanmu?","\n","ev","str","^Buka pintunya, masuk","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Urungkan — kembali ke lorong","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d1_room"},"\n",null],"c-1":["^ ",{"->":"opening"},"\n",null]}],null],"d1_b":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Kau mendorong pintu itu satu sentimeter. Dua sentimeter. Celah tipis menganga, dan kau mengintip dengan satu mata.","\n","^Gelap. Bau lembap yang lebih pekat menyeruak keluar. Samar-samar kau bisa melihat bentuk-bentuk: meja terbalik, kaki kursi yang patah. Tidak ada gerakan.","\n","^Tapi di ujung penglihatanmu, ada sesuatu yang berkilau redup di lantai — seperti bungkus plastik.","\n",{"->":"d1_b2"},null],"d1_b2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Celah itu menunggu. Keputusanmu?","\n","ev","str","^Masuk dan periksa","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Tutup perlahan, jangan ambil risiko","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d1_room"},"\n",null],"c-1":["^ ",{"->":"opening"},"\n",null]}],null],"d1_c":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Kau menarik napas, lalu mendorong pintu itu lebar-lebar.","\n","^KRIIEEK.","\n","^Engsel berkarat itu menjerit — suaranya memantul di sepanjang lorong, terlalu keras, terlalu lama. Jantungmu berhenti sesaat. Kau berdiri mematung, menunggu. Apakah ada yang mendengar?","\n","^Satu detik. Dua detik. Tidak ada yang datang. Lorong kembali sunyi, seolah tidak terjadi apa-apa.","\n","^Ruangan di baliknya kosong dan gelap. Meja-meja terbalik. Hening.","\n",{"->":"d1_c2"},null],"d1_c2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Derit itu mungkin terdengar sampai ujung lorong. Keputusanmu?","\n","ev","str","^Masuk cepat sebelum ada yang datang","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Tutup dan mundur — terlalu berisik","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d1_room"},"\n",null],"c-1":["^ ",{"->":"opening"},"\n",null]}],null],"d1_room":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Kau melangkah masuk. Udara di sini lebih dingin, dan baunya... tua. Seperti ruangan yang sudah bertahun-tahun tidak disentuh siapa pun.","\n","^Meja-meja terbalik berserakan. Di sudut, ada noda gelap di lantai — besar, tidak beraturan, meresap ke dalam beton. Kau tidak mau terlalu memikirkan apa itu.","\n","^Di bawah salah satu meja yang masih berdiri, ada sesuatu: sebungkus plastik bening berisi roti kering. Dan di sampingnya, selembar surat terlipat yang sudah menguning.","\n","ev","str","^Ambil bungkusan itu","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Periksa noda gelap itu dulu","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d1_loot"},"\n",null],"c-1":["^ ",{"->":"d1_stain"},"\n",null]}],null],"d1_stain":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Kau berjongkok di dekat noda itu. Warnanya cokelat kehitaman, tepinya tidak rata — merembes, bukan tumpah. Bau besi samar masih tercium jika kau mendekat.","\n","^Darah. Sudah sangat lama. Kering sepenuhnya.","\n","^Kau tidak tahu apakah itu membuatmu lega atau justru lebih takut.","\n",{"->":"d1_stain2"},null],"d1_stain2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","^Noda itu tidak menjawab apa-apa. Bungkusan di bawah meja masih di sana.","\n","ev","str","^Kembali dan ambil bungkusan itu","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Tinggalkan semuanya, keluar dari sini","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d1_loot"},"\n",null],"c-1":["^ ",{"->":"d1_empty"},"\n",null]}],null],"d1_loot":["#","^TAG:[Aman]","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","ev","str","^roti_kering","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev","str","^surat_terlipat","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d1","re":true},"^Kau meraih bungkusan plastik itu. Roti kering — tiga potong, masih dalam kemasan. Di sampingnya, surat terlipat itu terasa rapuh di jarimu.","\n","^Kau membukanya sekilas: tulisan tangan yang gemetar. 'Maafkan aku. Aku tidak bisa pulang. Jangan cari aku.' Tidak ada nama. Tidak ada tanggal.","\n","^Kau melipatnya kembali dan menyimpan keduanya. Setidaknya, perutmu tidak akan kosong untuk sementara waktu.","\n",{"->":"opening"},null],"d1_empty":["#","^TAG:[Aman]","/#","#","^AUDIO:saferoom","/#","#","^IMAGE:bg_saferoom","/#","ev",true,"/ev",{"VAR=":"f_d1","re":true},"^Kau memutuskan bungkusan itu tidak sepadan dengan firasat burukmu. Kau keluar dan menutup pintu perlahan.","\n","^Lorong menyambutmu kembali — sama gelapnya, sama sunyinya.","\n",{"->":"opening"},null],"d2_hub":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","^Pintu kedua di kiri terbuka lebar, setengah rusak — kayunya retak, tergantung miring di satu engsel.","\n","^Di baliknya: ruang sempit yang dipenuhi lemari-lemari tua berderet, seperti arsip atau gudang penyimpanan. Bau kapur barus dan kayu lapuk menyambutmu.","\n","^Semuanya diam. Terlalu diam?","\n","ev","str","^Lempar kerikil ke dalam, dengarkan","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Masuk dan buka lemari satu per satu","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Firasat buruk — mundur","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"d2_a"},"\n",null],"c-1":["^ ",{"->":"d2_room"},"\n",null],"c-2":["^ ",{"->":"d2_c"},"\n",null]}],null],"d2_a":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","^Kau memungut pecahan kaca dari lantai dan melemparkannya ke dalam ruangan. KLONTANG — memantul di lantai beton, menggelinding.","\n","^Sunyi. Lalu... dari dalam salah satu lemari, terdengar bunyi pelan: tuk.","\n","^Seperti sesuatu yang jatuh. Atau bergeser.","\n","^Kau menunggu. Tidak ada lagi.","\n",{"->":"d2_a2"},null],"d2_a2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Bunyi itu tidak terulang. Keputusanmu?","\n","ev","str","^Masuk dan periksa","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Batalkan — kembali ke lorong","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d2_room"},"\n",null],"c-1":["^ ",{"->":"opening"},"\n",null]}],null],"d2_c":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","^Kau mempercayai firasatmu dan melangkah mundur.","\n","^Tidak terjadi apa-apa. Dan justru itu yang mengganggumu — keheningan ruangan itu terasa... memperhatikan.","\n",{"->":"opening"},null],"d2_room":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","^Ruangan sempit. Tiga lemari tua berderet di dinding, pintunya kusam. Bau kapur barus menusuk hidung.","\n","^Lemari pertama: pintunya sedikit terbuka. Lemari kedua: tertutup rapat. Lemari ketiga: terkunci — dan di permukaannya ada goresan-goresan panjang. Dari dalam.","\n","ev","str","^Buka lemari pertama","/str",{"VAR?":"f_d2c1"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Buka lemari kedua","/str",{"VAR?":"f_d2c2"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Periksa lemari ketiga yang terkunci","/str",{"VAR?":"f_d2c3"},"!","/ev",{"*":".^.c-2","flg":21},"ev","str","^Keluar dari ruangan ini","/str","/ev",{"*":".^.c-3","flg":4},{"c-0":["\n","ev",true,"/ev",{"VAR=":"f_d2c1","re":true},{"->":"d2_c1"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"f_d2c2","re":true},{"->":"d2_c2"},{"#f":5}],"c-2":["\n","ev",true,"/ev",{"VAR=":"f_d2c3","re":true},{"->":"d2_c3"},{"#f":5}],"c-3":["^ ",{"->":"d2_done"},"\n",null]}],null],"d2_c1":["#","^TAG:[Aman]","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","ev","str","^perban_kotor","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d2c1","re":true},"^Kosong. Hanya debu tebal dan bau apek. Tapi di sudut bawahnya ada sesuatu yang terlipat: sepotong kain putih kusam — perban, masih digulung, meski kotor.","\n","^Kau mengambilnya. Lebih baik daripada tidak sama sekali. Mungkin.","\n",{"->":"d2_room"},null],"d2_c2":["#","^TAG:[Aman]","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","ev","str","^Sedih","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev","str","^cokelat","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d2c2","re":true},"^Kau membuka lemari kedua — dan sesuatu jatuh dari rak atas: sepatu kecil. Sepatu anak.","\n","^Kau menatapnya sesaat, lalu memaksakan diri melihat isi lemari: di rak bawah ada sebatang cokelat yang masih terbungkus rapat. Sedikit meleleh, tapi utuh.","\n","^Kau mengambil cokelat itu. Sepatu itu kau biarkan. Kau tidak sanggup menyentuhnya.","\n",{"->":"d2_room"},null],"d2_c3":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","^Kau mendekati lemari ketiga. Terkunci. Goresan-goresan panjang menghiasi pintunya — dalam, berulang, seperti dibuat dengan kuku. Dari dalam.","\n","^Kau menempelkan tangan ke kayunya. Dingin.","\n",{"->":"d2_c3x"},null],"d2_c3x":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","^Lemari itu diam. Terlalu diam.","\n","ev","str","^Tempelkan telinga, dengarkan","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Jangan sentuh — jauhi","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d2_c3b"},"\n",null],"c-1":["^ ",{"->":"d2_c3c"},"\n",null]}],null],"d2_c3b":["#","^TAG:[Aman]","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","ev","str","^Stress","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev","str","^Takut","/str",2,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d2c3","re":true},"^Sunyi... lalu: napas. Pelan, berat, tepat di balik kayu tipis itu.","\n","^Kau melompat mundur, jantung menghantam rusuk. Napas itu berhenti. Tidak ada lagi.","\n","^Apapun itu — ia masih di sana. Atau baru saja pergi. Kau tidak mau tahu.","\n",{"->":"d2_room"},null],"d2_c3c":["#","^TAG:[Aman]","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","ev","str","^Lega","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d2c3","re":true},"^Kau mundur perlahan, tidak melepaskan pandangan dari lemari itu.","\n","^Tidak terjadi apa-apa. Untuk kali ini, kehati-hatianmu terbayar.","\n",{"->":"d2_room"},null],"d2_done":["#","^TAG:[Aman]","/#","#","^AUDIO:darkstare","/#","#","^IMAGE:bg_darkstare","/#","ev",true,"/ev",{"VAR=":"f_d2","re":true},"^Kau keluar dari ruang lemari dan kembali ke lorong.","\n","^Di belakangmu, ruangan itu kembali sunyi — tapi kau tidak bisa menghilangkan perasaan bahwa keheningan itu menunggu.","\n",{"->":"opening"},null],"d3_hub":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","^Pintu pertama di kanan berayun pelan. Berderit kecil. Tidak ada angin — tapi ia bergerak, seperti dihembus sesuatu yang tidak terlihat.","\n","^Dari celahnya, kau mendengar sesuatu: detak. Pelan, berirama. Seperti... detak jantung? Atau jam?","\n","^Udara yang keluar dari celah itu dingin. Tidak wajar dinginnya.","\n","ev","str","^Ikuti suara detak itu — masuk","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Diam di ambang pintu, amati dulu","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Mundur perlahan, tutup pintu","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"d3_a"},"\n",null],"c-1":["^ ",{"->":"d3_b"},"\n",null],"c-2":["^ ",{"->":"d3_c"},"\n",null]}],null],"d3_a":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","^Kau melangkah masuk. Dingin langsung merayap naik dari kakimu, seperti air es.","\n","^Detak itu semakin jelas — tapi kau sadar, itu bukan jam. Terlalu tidak beraturan. Terlalu... hidup.","\n","^Lalu kau melihatnya. Di sudut ruangan, udara beriak seperti air — dan sepasang mata merah menyala membuka di dalam kegelapan yang tak berwujud.","\n","^Ia melihatmu.","\n",{"->":"d3_a2"},null],"d3_a2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","ev","str","^Takut","/str",2,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Mata merah itu menyipit. Ia mulai bergerak ke arahmu.","\n","ev","str","^Beku — jangan bergerak sama sekali","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Putar balik dan LARI","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"d3_a2a"},"\n",null],"c-1":["^ ",{"->":"d3_a2b"},"\n",null]}],null],"d3_a2a":["#","^TAG:[Dalam bahaya]","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","ev","str","^danger","/str",{"x()":"SET_STATUS","exArgs":1},"pop","/ev","\n","ev","str","^Stress","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d3","re":true},"^Kau memaksa tubuhmu diam. Jangan bernapas. Jangan berkedip.","\n","^Sosok transparan itu melayang mendekat. Dingin menusuk tulangmu saat ia mengitarimu — kau bisa merasakan kebencian memancar darinya, seperti radiasi.","\n","^Lalu... ia berhenti. Mata merah itu menyipit. Perlahan, ia mundur, melebur kembali ke dalam kegelapan ruangan.","\n","^Kau tidak tahu kenapa ia melepaskanmu. Kau tidak mau tahu. Kakimu gemetar saat kau melangkah mundur keluar.","\n",{"->":"opening"},null],"d3_a2b":["#","^TAG:[Terluka]","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","ev","str","^wounded","/str",{"x()":"SET_STATUS","exArgs":1},"pop","/ev","\n","ev","str","^Stress","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev","str","^Lengan Kiri Tergores","/str",{"x()":"SET_BODY","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d3","re":true},"^Kau berbalik dan lari — tapi ia lebih cepat.","\n","^Dingin membakar lengan kirimu saat sesuatu yang tak terlihat mencakar lewat. Kau terhuyung, tapi terus berlari, menerobos pintu dan membantingnya di belakangmu.","\n","^Napasmu memburu. Lengan kirimu perih — tiga garis merah menganga di kulitmu, dan dinginnya masih terasa menusuk sampai ke tulang.","\n","^Kau terluka. Dan kau sadar satu hal: ia tidak mengejarmu keluar. Ia hanya... menjaga ruangan itu.","\n",{"->":"opening"},null],"d3_b":["#","^TAG:[Dalam bahaya]","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","ev","str","^danger","/str",{"x()":"SET_STATUS","exArgs":1},"pop","/ev","\n","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d3","re":true},"^Kau tetap di ambang pintu, tidak masuk. Hanya mengamati.","\n","^Detak itu berlanjut. Lalu, perlahan, sepasang mata merah menyala muncul dari kegelapan — dan menatap lurus ke arahmu.","\n","^Kau tidak bergerak. Ia tidak bergerak. Waktu berhenti.","\n","^Kemudian mata itu berkedip — sekali — dan menghilang. Detak itu pun berhenti.","\n","^Pesannya jelas: ia tahu kau di sini. Dan ia membiarkanmu pergi. Untuk sekarang.","\n",{"->":"opening"},null],"d3_c":["#","^TAG:[Aman]","/#","#","^AUDIO:teddyroom","/#","#","^IMAGE:bg_teddyroom","/#","ev","str","^Stress","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d3","re":true},"^Kau mundur selangkah. Dua langkah. Tanganmu meraih gagang pintu.","\n","^Tepat saat pintu hampir tertutup, detak itu... berhenti.","\n","^Hening total. Lalu, dari balik pintu yang nyaris rapat, terdengar bunyi gesekan pelan — seperti kuku di kayu. Sekali. Dua kali.","\n","^Kau menutup pintu sepenuhnya dan mundur. Jantungmu masih berdebar lama setelahnya.","\n",{"->":"opening"},null],"d4_hub":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Pintu kedua di kanan lebih tenang. Dari celahnya, kau bisa melihat sebuah meja — dan di atasnya, bayangan samar.","\n","^Kau mendorong pintu itu. Ruangan kecil. Meja kayu di tengah. Dan di atasnya...","\n","^Sebuah boneka beruang. Usang, satu matanya lepas, tapi bersih — terlalu bersih untuk tempat ini. Seolah seseorang merawatnya.","\n","ev","str","^Ambil bonekanya langsung","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Periksa meja dan sekitarnya dulu","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Jangan sentuh apa pun — pergi","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"d4_a"},"\n",null],"c-1":["^ ",{"->":"d4_b"},"\n",null],"c-2":["^ ",{"->":"d4_c"},"\n",null]}],null],"d4_a":["#","^TAG:[Aman]","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","ev","str","^Lega","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev","str","^boneka","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d4","re":true},"^Kau mengangkat boneka itu. Ringan. Dan... hangat.","\n","^Kehangatan yang aneh menjalar ke tanganmu — seperti baru saja dipeluk seseorang. Kau merinding.","\n","^Lalu kau menyadarinya: mata boneka yang masih ada itu... menatapmu. Tadi, saat di atas meja, ia menghadap ke arah lain. Bukankah begitu?","\n","^Kau memeluknya erat-erat. Entah kenapa, benda ini terasa penting.","\n",{"->":"opening"},null],"d4_b":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Kau menahan diri dan memeriksa ruangan dulu. Meja itu kosong selain boneka. Tapi di bawah meja, terselip sesuatu: selembar kertas gambar anak-anak, digambar dengan crayon.","\n","^Gambarnya: sebuah keluarga — ayah, ibu, anak — bergandengan tangan. Dan di belakang mereka, sosok tinggi hitam dengan mata merah.","\n","^Crayon merahnya ditekan begitu keras sampai kertasnya sobek tepat di bagian mata itu.","\n",{"->":"d4_b2"},null],"d4_b2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Gambar itu terasa dingin di jarimu. Boneka itu masih di atas meja.","\n","ev","str","^Ambil bonekanya juga","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Ambil gambarnya saja, tinggalkan boneka","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Tinggalkan semuanya","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"d4_a"},"\n",null],"c-1":["^ ",{"->":"d4_draw"},"\n",null],"c-2":["^ ",{"->":"d4_c"},"\n",null]}],null],"d4_draw":["#","^TAG:[Aman]","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev","str","^gambar_crayon","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d4","re":true},"^Kau mengambil gambar itu dan melipatnya hati-hati. Bonekanya kau biarkan di atas meja.","\n","^Saat kau berbalik, dari sudut matamu — kau bersumpah kepala boneka itu sedikit miring. Mengikutimu.","\n","^Kau tidak menoleh lagi.","\n",{"->":"opening"},null],"d4_c":["#","^TAG:[Aman]","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","ev","str","^Stress","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev","str","^Takut","/str",2,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_d4","re":true},"^Kau memutuskan untuk tidak menyentuh apa pun. Nalurimu berteriak.","\n","^Kau melangkah mundur menuju pintu. Dan saat itulah kau mendengarnya — pelan, hampir tidak ada:","\n","^'...jangan pergi.'","\n","^Suaranya seperti anak kecil. Berasal dari... boneka itu? Atau dari kepalamu sendiri?","\n","^Kau keluar dan menutup pintu. Tanganmu gemetar.","\n",{"->":"opening"},null],"d5_1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","^Kau mengabaikan pintu-pintu itu dan terus melangkah ke ujung lorong.","\n","^Lampu-lampu di sini berkedip makin cepat. Langkah kakimu bergema... dan kau menyadarinya: gemanya salah. Ada setengah ketukan tambahan di antara langkahmu — seperti ada yang berjalan bersamamu, sedikit tidak selaras.","\n","^Kau berhenti. Gema itu berhenti... setengah detik lebih lambat.","\n","^Di depan, deretan lampu di langit-langit berkedip liar — kecuali satu. Satu lampu menyala stabil, terang, mengundang.","\n","^Di bawah lampu yang stabil itu, kau melihat sesuatu yang janggal: lantainya bersih. Tidak ada debu, tidak ada puing — padahal seluruh lorong ini kotor. Seperti tempat itu... dirawat. Atau sering ditunggu.","\n","^Dan kau teringat: tadi, saat bayangan besar melintas di kejauhan, setiap lampu yang dilewatinya berkedip liar.","\n",{"->":"d5_1c"},null],"d5_1c":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Gema langkah itu masih ada — setengah ketukan di belakangmu. Lampu yang stabil itu menunggu.","\n","^Apa yang akan kau lakukan?","\n","ev","str","^Berlari ke lampu yang stabil — terang berarti aman (butuh 15 energi)","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Bergerak di antara kedipan, tetap dalam bayangan — Butuh fokus (mental ≤ Gelisah)","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Berbalik kembali ke persimpangan pintu","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"d5_trap"},"\n",null],"c-1":["^ ",{"->":"d5_smart"},"\n",null],"c-2":["^ ",{"->":"d5_back"},"\n",null]}],null],"d5_trap":["#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","^Kau berlari menuju cahaya. Terang berarti aman — itu naluri, itu logika.","\n","^Cahaya itu menyilaukan. Kau tidak melihat kegelapan di sekitarnya — dan di situlah ia berdiri.","\n","^Sosok besar tanpa kepala. Bertangan banyak. Kapak besar terangkat.","\n","^Lampu yang stabil itu bukan tempat aman. Itu tempatnya menunggu. Lampu-lampu lain berkedip karena ia lewat — yang satu ini stabil karena ia tidak pernah pergi.","\n","^Kau tak sempat menyesal.","\n","ev",{"x()":"DEATH"},"pop","/ev","\n","end",null],"d5_smart":["#","^TAG:[Aman]","/#","#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","ev","str","^Kelelahan","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Kau memaksa kakimu diam. Bernapas pelan. Mengamati.","\n","^Pola kedip lampu-lampu itu... tidak acak. Setiap beberapa detik, satu lampu berkedip liar — berpindah, mendekat. Sesuatu bergerak di lorong itu, dari lampu ke lampu.","\n","^Kau bergerak hanya saat lampu di depanmu padam dalam kedipnya — berlari pendek dalam gelap, berhenti dalam bayangan. Jantungmu menghantam rusuk, tapi kau tidak berhenti.","\n","^Saat kau melewati lampu yang stabil itu, kau tidak menoleh. Kau sudah tahu apa yang menunggu di sana.","\n","^Lorong terbuka ke sebuah pertigaan. Kau berhasil.","\n",{"->":"hub_exit"},null],"d5_back":["#","^TAG:[Aman]","/#","#","^AUDIO:doorhub","/#","#","^IMAGE:bg_doorhub","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Kau berbalik — perlahan, tanpa membelakangi kegelapan terlalu lama.","\n","^Gema setengah ketukan itu mengikutimu beberapa langkah, lalu... hilang. Seperti tidak pernah ada.","\n","^Kau kembali ke persimpangan pintu dengan napas memburu. Setidaknya kau masih hidup.","\n",{"->":"opening"},null],"hub_exit":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Langkah-langkahmu melambat, nyaris tanpa suara di atas lantai yang dingin, hingga kau tiba di sebuah pertigaan lorong. Di tengahnya, seperti bangkai hewan purba, berdiri meja resepsionis tua yang nyaris hancur — permukaannya retak, tepinya mengelupas, dan di atasnya berserakan tumpukan kertas yang telah menjadi sarang debu. Dari balik meja itu, dua lorong lain membentang: yang kiri tenggelam dalam kegelapan pekat, sunyi hingga kau bisa mendengar darahmu sendiri berdenyut di telinga; yang kanan, di ujungnya, memancarkan secercah cahaya redup yang bergoyang pelan, seolah mengundangmu mendekat — atau memancingmu.","\n","^Kau menarik napas, dan udara di sini terasa salah — berat, pengap, seakan tempat ini menyimpan terlalu banyak hal yang tak seharusnya diingat. Dan suara-suara itu… bisikan-bisikan samar yang sejak tadi mengikutimu, kini terdengar lebih dekat, merayap di sepanjang dinding seperti sesuatu yang hidup, menolak pergi, menolak membiarkanmu sendirian dengan pikiranmu sendiri.","\n",{"->":"reception_hub"},null],"reception_hub":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Kau berdiri di jantung pertigaan itu, dikelilingi kebisuan yang terasa berat menekan kulitmu. Meja resepsionis yang hancur itu membusuk dalam diam di tengah ruangan, tumpukan kertas berdebu di atasnya seolah menyimpan rahasia yang tak berani dibuka. Lorong kiri menganga gelap dan sunyi, menelan setiap suara; lorong kanan menjanjikan cahaya redup yang tak bisa sepenuhnya kau percaya. Dan di antara semuanya, suara-suara aneh itu masih berkeliaran — samar, sabar, menghantuimu.","\n","ev","str","^Periksa area sekitar meja resepsionis","/str",{"VAR?":"f_rec_desk"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Masuki lorong kiri yang gelap dan sunyi","/str",{"VAR?":"f_rec_left"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Periksa tumpukan kertas di atas meja","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["\n","ev",true,"/ev",{"VAR=":"f_rec_desk","re":true},{"->":"rec_desk_1"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"f_rec_left","re":true},{"->":"rec_left_1"},{"#f":5}],"c-2":["^ ",{"->":"rec_papers_1"},"\n",null]}],null],"rec_desk_1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Kau berjongkok di sisi meja, dan lututmu langsung tenggelam dalam lapisan debu yang tebalnya hampir seperti kain. Bau apek menyengat naik ke hidungmu — bau kertas busuk, kayu lapuk, dan sesuatu yang lebih tua, lebih manis, yang tak ingin kau kenali. Kolong meja di hadapanmu gelap seperti mulut yang menganga, menolak memantulkan cahaya apa pun.","\n","^Jari-jarimu meraba di antara serpihan-serpihan tak dikenal — pecahan yang tajam di satu sisi, lunak dan berlendir di sisi lain — hingga ujung jarimu menyentuh sesuatu yang berbeda: kecil, bulat, dan dingin seperti es, tergeletak diam di lantai yang berdebu.","\n",{"->":"rec_desk_2"},null],"rec_desk_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Kau masih berjongkok, napasmu tertahan, dan dalam gelap kolong meja itu dua hal menarik perhatianmu: lantai berdebu yang dingin di bawah telapak tanganmu, dan gundukan puing di sekitar kaki meja — keduanya seolah menyimpan sesuatu yang menunggu ditemukan.","\n","ev","str","^Raba lantai berdebu di kolong meja","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Periksa puing di sekitar kaki meja","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"rec_desk_floor"},"\n",null],"c-1":["^ ",{"->":"rec_desk_rubble"},"\n",null]}],null],"rec_desk_floor":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Kau meraba dalam kegelapan kolong meja, jari-jarimu menyapu lantai yang dingin dan berpasir. Lalu — sentuhan logam. Kecil, bulat, dingin menusuk, dengan permukaan kasar yang menggores kulitmu. Jantungmu berdebar sedikit lebih kencang, tanpa alasan yang jelas.","\n","^Kau menariknya keluar ke cahaya: sebuah koin logam tua, permukaannya begitu kusam hingga nyaris hitam, tepiannya terkikis waktu. Tidak ada ukiran yang bisa dikenali, tidak ada kilau, tidak ada makna. Tidak istimewa — tapi nyata, berat di telapak tanganmu, sebuah benda yang pernah disentuh tangan orang lain di tempat yang sudah lama mati ini.","\n",{"->":"rec_desk_floor_2"},null],"rec_desk_floor_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Koin itu tergeletak di telapak tanganmu yang kotor, dinginnya perlahan meresap ke kulitmu, seolah menuntut sebuah keputusan.","\n","ev","str","^Ambil koin itu","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Biarkan saja di sana","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"rec_coin"},"\n",null],"c-1":["^ ",{"->":"rec_desk_back"},"\n",null]}],null],"rec_desk_rubble":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Kau menggeser puing-puing itu satu per satu: pecahan ubin yang tajam seperti gigi, sebuah cangkir kertas yang penyok dan menguning, pulpen plastik yang tintanya sudah lama kering. Sampah-sampah biasa dari sebuah kehidupan yang sudah berhenti.","\n","^Lalu matamu menangkap selembar kertas robek, terjepit di bawah pecahan ubin. Di atasnya, dengan tinta yang memudar, tertulis setengah kalimat: '...jangan percaya...' — dan sisanya hilang, terkoyak bersama separuh kertas yang tak pernah ditemukan. Jari-jarimu gemetar sedikit saat memegangnya.","\n","^Kau mengobrak-abrik sisa puing itu, tapi tidak ada lagi. Hanya debu yang beterbangan dan menempel di tenggorokanmu, dan bau apek yang semakin pekat, seolah tempat ini kecewa kau tidak menemukan apa-apa.","\n",{"->":"rec_desk_rubble_2"},null],"rec_desk_rubble_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Puing itu tidak menyimpan apa-apa lagi — hanya bisu, debu, dan bau lapuk yang menempel di pakaianmu.","\n","ev","str","^Kembali berdiri","/str","/ev",{"*":".^.c-0","flg":4},{"c-0":["^ ",{"->":"rec_desk_back"},"\n",null]}],null],"rec_coin":["#","^KICKER:Part 1 : Awal Mula","/#","#","^TAG:[Aman]","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","ev","str","^koin_logam","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_rec_coin","re":true},"ev",true,"/ev",{"VAR=":"f_rec_desk","re":true},"^Kau memungut koin itu. Kusam, ringan, biasa saja — dinginnya menusuk telapak tanganmu sesaat sebelum perlahan menghangat oleh panas tubuhmu. Tidak ada ukiran rahasia, tidak ada petunjuk tersembunyi, tidak ada bisikan dari masa lalu.","\n","^Hanya sebuah koin tua. Benda mati dari tempat yang mati. Kau menyimpannya ke dalam saku — bukan karena berharga, tapi karena di tempat seperti ini, sesuatu yang nyata terasa lebih baik daripada tidak memegang apa-apa.","\n",{"->":"reception_hub"},null],"rec_desk_back":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","ev",true,"/ev",{"VAR=":"f_rec_desk","re":true},"^Kau berdiri, menepuk debu dari lututmu hingga awan kelabu kecil beterbangan di udara. Area meja tidak menyimpan apa-apa lagi — hanya bangkai kayu tua dan tumpukan kertas yang akan terus membusuk dalam diam.","\n","^Di belakangmu, pertigaan itu menunggumu kembali: lorong kiri yang gelap gulita, lorong kanan dengan cahaya redupnya, dan suara-suara aneh yang tak pernah benar-benar pergi.","\n",{"->":"reception_hub"},null],"rec_left_1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:leftcorridor","/#","#","^IMAGE:bg_leftcorridor","/#","^Kau melangkah ke lorong kiri, dan seketika dunia di belakangmu terasa runtuh. Udara di sini berbeda — lebih dingin, lebih lembap, lebih berat, seperti paru-paru tempat ini sendiri sedang membusuk perlahan. Setiap langkahmu bergema pelan di lantai beton, sebuah bunyi yang tidak pantas terdengar sendirian di tempat sepi ini.","\n","^Kegelapan di lorong ini lebih tebal, lebih rakus. Ia menelan cahaya dari pertigaan di belakangmu satu langkah demi langkah, sampai yang tersisa hanyalah selaput hitam yang menutup di sekelilingmu. Lorong ini pendek — kau merasakannya dari cara dinding-dindingnya menutup di kejauhan — tetapi setiap meter terasa seperti ditarik mundur ke dalam sebuah rahang yang perlahan menutup.","\n",{"->":"rec_left_2"},null],"rec_left_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:leftcorridor","/#","#","^IMAGE:bg_leftcorridor","/#","^Di ujung lorong — tanpa pintu samping, tanpa celah apa pun — berdiri sebuah pintu baja tebal. Logamnya memantulkan sisa cahaya dengan dingin, kusam, dan tak bersahabat. Lorong ini buntu. Kakimu telah membawamu sejauh ia bisa melangkah, dan satu-satunya yang menunggumu di sini hanyalah diamnya baja itu.","\n","ev","str","^Melangkah perlahan ke pintu baja","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Kembali ke pertigaan","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"rec_left_door"},"\n",null],"c-1":["^ ",{"->":"rec_left_back"},"\n",null]}],null],"rec_left_door":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:steeldoor","/#","#","^IMAGE:bg_steeldoor","/#","#","^SFX:door_creak","/#","^Kau menatap pintu baja itu dari dekat, dan napasmu tercekat. Ia terkunci rapat — tidak ada gagang, tidak ada lubang kunci, bahkan tidak ada celah yang cukup lebar untuk menyelipkan ujung jari. Permukaannya dingin dan licin di bawah sentuhanmu, seperti kulit hewan yang sudah lama mati.","\n","^Lalu kau melihatnya. Goresan-goresan dalam membelah permukaan baja itu, berulang dan sejajar — bekas cakaran. Kau menelan ludah; tidak ada manusia yang cakarnya sanggup menembus logam setebal ini. Sesuatu yang jauh lebih kuat dari manusia pernah mencoba mendobrak... dari sisi lain.","\n",{"->":"rec_left_door_2"},null],"rec_left_door_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:steeldoor","/#","#","^IMAGE:bg_steeldoor","/#","#","^SFX:door_creak","/#","^Pintu itu diam — diam yang tidak wajar, diam yang seolah sedang menahan napas. Dari celah tipis di bawahnya merembes bau besi berkarat, dan di baliknya... sesuatu yang busuk, samar, seperti daging yang dibiarkan membusuk di ruangan tanpa udara. Bau itu membuat perutmu mual.","\n","ev","str","^Dorong pintu baja itu","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Telusuri goresan di permukaan pintu","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Kembali ke pertigaan","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"rec_left_push"},"\n",null],"c-1":["^ ",{"->":"rec_left_scratch"},"\n",null],"c-2":["^ ",{"->":"rec_left_back"},"\n",null]}],null],"rec_left_push":["#","^KICKER:Part 1 : Awal Mula","/#","#","^TAG:[Aman]","/#","#","^AUDIO:steeldoor","/#","#","^IMAGE:bg_steeldoor","/#","#","^SFX:metal_clang","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_rec_left","re":true},"^Kau menahan napas dan mendorong sekuat tenaga — bahumu menabrak logam yang dingin itu, otot-ototmu menegang sampai gemetar. Pintu itu tidak bergeming sedikit pun, seolah telah dilas mati oleh dunia ini sendiri.","\n","^Lalu — dentum pelan, dalam, yang menggema di dadamu seperti jantung kedua. Hening. Dan dari sisi lain pintu itu... terdengar sesuatu yang bergeser. Pelan. Berat. Menjauh, atau mendekat — kau tidak bisa tahu. Kakimu memutuskan lebih dulu daripada kepalamu: kau mundur, tangan gemetar, napas tercekat di tenggorokan.","\n",{"->":"reception_hub"},null],"rec_left_scratch":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:steeldoor","/#","#","^IMAGE:bg_steeldoor","/#","^Ujung jarimu menelusuri goresan itu, dan kau merasakan logam yang terkoyak — dalam, kasar, tak kenal ampun. Goresan-goresan itu berulang dalam pola sejajar, ritmis, seperti cakaran yang menyerang lagi dan lagi. Terlalu lebar untuk tangan manusia. Terlalu dalam untuk sesuatu yang bukan binatang... atau sesuatu yang lebih buruk dari binatang.","\n","^Dan kemudian darahmu menjadi es. Sudut-sudut sobekannya — kau melihatnya sekarang — menunjuk ke dalam, ke arahmu. Goresan ini tidak dibuat dari sisi luar. Goresan ini berasal dari SISI DALAM pintu. Sesuatu di balik baja itu pernah mencoba... KELUAR.","\n",{"->":"rec_left_door_2"},null],"rec_left_back":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:leftcorridor","/#","#","^IMAGE:bg_leftcorridor","/#","ev",true,"/ev",{"VAR=":"f_rec_left","re":true},"^Kau melangkah mundur perlahan, kaki terseret, tidak pernah melepaskan pandangan dari pintu baja itu. Setiap langkah mundur terasa seperti menarik dirimu keluar dari mulut sesuatu yang sedang tidur.","\n","^Di pertigaan, cahaya menyambutmu dengan samar — dan baru di sana kau menyadari napasmu memburu, keringat dingin membasahi tengkuk. Kau telah kembali. Tetapi di punggungmu, lorong kiri itu tetap menganga, dan kau tidak berani membelakanginya terlalu lama.","\n",{"->":"reception_hub"},null],"rec_papers_1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","#","^SFX:paper_rustle","/#","^Kau mendekati meja resepsionis. Di atasnya: tumpukan kertas berdebu, beberapa terikat tali yang sudah lusuh dan lapuk, tepi-tepinya menguning dimakan waktu. Debu beterbangan di udara saat kau bergerak, menari dalam cahaya samar seperti abu dari sesuatu yang terbakar lama.","\n","^Lembar paling atas menyambutmu dengan tulisan tangan yang besar dan tergesa: 'Eksperimen Subjek ke-X'. Huruf-hurufnya miring, ditekan keras sampai menembus kertas. Jantungmu berdebar begitu keras hingga kau yakin lorong-lorong kosong ini bisa mendengarnya.","\n",{"->":"rec_papers_2"},null],"rec_papers_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","^Kertas-kertas itu menunggu — diam, sabar, seolah mereka sudah menunggu seseorang selama bertahun-tahun. Ujung-ujungnya bergetar diterpa udara dingin... atau itu tanganmu yang gemetar. Kau tidak bisa lagi membedakannya.","\n","ev","str","^Baca lembar paling atas","/str",{"VAR?":"f_rec_read"},"!","/ev",{"*":".^.c-0","flg":21},"ev","str","^Lihat foto-foto terlampir","/str",{"VAR?":"f_rec_photos"},"!","/ev",{"*":".^.c-1","flg":21},"ev","str","^Ambil beberapa lembar yang utuh","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["\n","ev",true,"/ev",{"VAR=":"f_rec_read","re":true},{"->":"rec_papers_read"},{"#f":5}],"c-1":["\n","ev",true,"/ev",{"VAR=":"f_rec_photos","re":true},{"->":"rec_papers_photos"},{"#f":5}],"c-2":["^ ",{"->":"rec_papers_take"},"\n",null]}],null],"rec_papers_read":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","#","^SFX:paper_rustle","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_rec_read","re":true},"^Catatan itu ditulis dengan ketenangan yang menjijikkan. Setiap halaman menjabarkan prosedurnya secara rinci dan dingin — bagaimana seorang manusia dibelah, dipotong-potong, lalu disusun ulang dengan bagian-bagian yang tidak semestinya menempel pada tubuh siapa pun. Langkah demi langkah, tanpa ragu, sampai yang tersisa tidak lagi bisa disebut manusia. Hanya disebut sebagai... subjek.","\n","^Lambungmu bergejolak, asam naik sampai ke tenggorokan dan membakar. Tapi jemarimu terus membalik halaman, seolah tanganmu bergerak sendiri. Kau harus tahu. Kau harus tahu apa yang telah mereka lakukan di sini — dan apa yang mungkin sudah menunggumu di luar ruangan ini.","\n","^Setiap baris lebih buruk dari baris sebelumnya. Dan di suatu tempat di dalam kepalamu, sebuah suara kecil mulai bertanya dengan nada yang tidak ingin kau dengar: apakah mereka juga melakukan ini pada orang-orang sepertimu? Orang-orang yang terbangun tanpa ingatan apa pun?","\n",{"->":"rec_papers_2"},null],"rec_papers_photos":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","#","^SFX:paper_rustle","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","ev",true,"/ev",{"VAR=":"f_rec_photos","re":true},"^Di antara tumpukan kertas, ada amplop cokelat yang berat berisi foto-foto hitam putih. Yang gagal — dan yang, menurut tulisan tangan di bagian belakangnya, 'berhasil'. Tubuh-tubuh yang pernah menjadi manusia, dipajang seperti barang dagangan di atas baki-baki laboratorium, difoto dengan rapi seolah itu hal biasa.","\n","^Wajah-wajah itu masih menyerupai wajah. Itulah yang paling mengerikan. Kau memalingkan muka secepat mungkin, tapi sudah terlambat — gambar-gambar itu terbakar ke dalam kepalamu, tajam dan kejam, menolak pergi setiap kali kau berkedip.","\n","^Tanganmu gemetar begitu hebat hingga amplop itu hampir terlepas dari genggamanmu. Kau memaksakan diri menutupnya dan melemparkannya kembali ke tumpukan, tapi bau bahan kimia dari kertas foto itu masih menempel di hidungmu, menempel seperti kenangan.","\n",{"->":"rec_papers_2"},null],"rec_papers_take":["#","^KICKER:Part 1 : Awal Mula","/#","#","^TAG:[Canon]","/#","#","^AUDIO:reception","/#","#","^IMAGE:bg_reception","/#","ev","str","^Stress","/str",{"x()":"TIER_UP","exArgs":1},"pop","/ev","\n","ev","str","^catatan_eksperimen","/str",{"x()":"GRANT_ITEM","exArgs":1},"pop","/ev","\n","ev","str","^Sangat Mual","/str",{"x()":"SET_BODY","exArgs":1},"pop","/ev","\n","ev","str","^tier_tutorial","/str",{"x()":"TUT_POP","exArgs":1},"pop","/ev","\n","^Dengan tangan yang masih gemetar, kau menyambar beberapa lembar yang tampak paling utuh — yang tulisannya masih bisa terbaca, yang diagramnya belum robek. Kertasnya dingin dan licin oleh kelembapan di bawah jemarimu, dan kau melipatnya dengan hati-hati sebelum menyelipkannya jauh ke dalam saku.","\n","^Sekarang kau mengerti. Potongan-potongan yang kau lihat bergerak dalam gelap tadi, sosok-sosok yang mengintai di sudut ruangan — mereka semua adalah hasil dari eksperimen mengerikan ini. Mereka bukan monster yang lahir dari Kegelapan. Mereka dibuat. Dengan sengaja. Oleh tangan manusia.","\n","^Lambungmu bergejolak lagi, asam pahit membakar tenggorokanmu. Pikiranmu kacau, gambar-gambar itu terus bermunculan di balik kelopak matamu — tapi kau menyimpan catatan itu erat-erat. Di suatu tempat di dalam tulisan yang dingin itu mungkin tersembunyi kelemahan mereka. Dan kau tahu kau akan membutuhkannya.","\n",{"->":"s12_a"},null],"s12_a":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Kau mengikuti secercah cahaya redup yang merembes dari ujung lorong, berharap itu adalah jalan keluar. Kegelapan di belakangmu terasa menekan punggungmu seperti beban yang hidup, dan gambar-gambar dari catatan itu masih menempel di pelupuk matamu setiap kali kau berkedip — wajah-wajah itu, tubuh-tubuh itu.","\n","^Cahaya itu ternyata berasal dari lampu darurat yang tergantung miring di langit-langit aula yang luas — kedipannya tidak beraturan, menyalakan dan memadamkan ruangan dalam denyut merah yang menyakitkan mata. Udara dipenuhi bau debu, karat, dan sesuatu yang jauh lebih busuk, sesuatu yang manis dan membusuk sekaligus.","\n","^Kau mengintip dari balik kusen pintu yang retak — dan matamu terbelalak. Aula itu dipenuhi oleh mereka. Makhluk-makhluk hasil eksperimen, bergerak, bernapas, hidup. Puluhan. Mungkin lebih. Dan semuanya berada di antara kau dan sisi lain ruangan.","\n",{"->":"s12_b"},null],"s12_b":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Wujud mereka adalah penghinaan terhadap segala sesuatu yang seharusnya hidup. Tungkai-tungkai tambahan tumbuh dari punggung-punggung yang bungkuk, menyeret jejak basah yang mengilap di atas lantai beton. Beberapa tubuh membesar hingga pakaiannya — kalau itu masih bisa disebut pakaian — robek dan menggantung seperti kain kafan. Kulit sebagian di antara mereka begitu tipis hingga organ-organ di bawahnya berdenyut dengan jelas, merah dan basah dan hidup.","\n","^Sosok tinggi kurus berdiri di tengah aula, lengannya yang panjang menjuntai hingga ujung jarinya menyentuh lantai, jari-jari runcingnya menggores beton dengan bunyi berderit pelan setiap kali ia bergeser. Tidak jauh darinya, segumpalan daging merayap dengan kaki-kaki kecil yang tak terhitung jumlahnya, meninggalkan lendir asam yang mendesis pelan setiap kali menyentuh lantai.","\n","^Dari balik pilar yang runtuh, sesuatu mengawasimu — atau mengawasi ke arahmu. Ia memiliki mata yang terlalu banyak untuk satu kepala, berbaris dan berputar masing-masing dengan caranya sendiri. Satu di antaranya berhenti, tepat mengarah padamu. Jantungmu berhenti berdetak. Lalu mata itu berputar pergi, acuh, seolah kau tidak lebih penting dari debu yang menempel di lantai.","\n",{"->":"s12_c"},null],"s12_c":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","#","^SFX:whisper","/#","^DENTUMAN keras memecah udara dari sudut jauh aula — sesuatu yang besar jatuh dari langit-langit, menghantam lantai dengan gemerincing logam yang bergema panjang di antara dinding-dinding beton. Semua makhluk itu berhenti serentak, seperti satu tubuh. Puluhan kepala menoleh ke arah suara itu.","\n","^Beberapa di antara mereka mulai bergerak ke sana, langkah-langkah berat dan gesekan daging yang diseret memenuhi ruangan. Dan di saat yang bersamaan — dari lorong belakang, dari arah meja resepsionis — terdengar gemerusuk yang keras dan tergesa-gesa, seperti sesuatu yang menyeret tubuhnya sendiri dengan panik.","\n","^Lalu ia melesat melewatimu. Makhluk kecil gesit seukuran anjing, dengan kaki-kaki seperti serangga yang bergerak terlalu cepat untuk diikuti mata, melintas begitu dekat hingga hembusan anginnya menyentuh kulitmu. Jantungmu berhenti sesaat. Ia tidak berhenti. Ia tidak menoleh. Ia hanya... lewat, seolah kau bahkan tidak ada di sana.","\n",{"->":"s12_hub"},null],"s12_hub":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Kau berdiri di ambang pintu aula, sebagian tubuhmu masih tersembunyi di balik bayangan kusen yang retak. Di depanmu, kekacauan itu bergolak — makhluk-makhluk teralihkan, perhatian mereka tercerai-berai ke berbagai arah. Ini adalah kesempatan. Atau jebakan. Udara dingin menusuk paru-parumu, dan setiap detik yang kau habiskan untuk berpikir adalah satu detik lagi kau terlihat.","\n","ev","str","^Lari panik kembali ke meja resepsionis","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Bersembunyi di balik tumpukan peti tua","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Menyelinap melewati aula selagi mereka teralihkan","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"s12_panic"},"\n",null],"c-1":["^ ",{"->":"s12_hide_1"},"\n",null],"c-2":["^ ",{"->":"s12_run_1"},"\n",null]}],null],"faint_killed":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Dunia berputar. Lututmu lemas — kegelapan menelanmu dari tepi penglihatan.","\n","^Kau tidak pernah bangun.","\n","^Dalam gelap, sesuatu menemukan tubuhmu yang tak berdaya... dan berpesta.","\n","ev",{"x()":"DEATH"},"pop","/ev","\n","end",null],"rest_killed":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Kau memaksakan tubuhmu beristirahat — untuk keempat kalinya, di tempat yang sama, dengan cara yang sama.","\n","^Sesuatu sudah hafal polamu. Ia bahkan tidak perlu mengendap-endap.","\n","^Kau tidak pernah bangun.","\n","ev",{"x()":"DEATH"},"pop","/ev","\n","end",null],"s12_panic":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Rasa takut mengambil alih sepenuhnya. Ia tidak bertanya, tidak menunggu, tidak memberi pilihan — ia hanya menarik kakimu berbalik dan mendorong tubuhmu menjauh dari aula, dari makhluk-makhluk itu, dari segala hal yang tidak bisa kau pahami.","\n","^Kau mencoba keluar tanpa suara, langkahmu ditahan, napasmu dicekik di tenggorokan. Tapi lorong itu tidak kosong. Beberapa pasang mata menatapmu dari dalam kegelapan — mata-mata yang sepertinya sudah menunggumu sejak awal. Dan di antara mereka, sosok tinggi kurus itu bergerak. SANGAT cepat. Terlalu cepat untuk sesuatu setinggi itu.","\n","^Jari-jarinya yang runcing mencabik tubuhmu sebelum kau sempat berteriak, sebelum kau sempat berbuat apa-apa. Dunia menjadi merah, lalu gelap, lalu tidak ada sama sekali.","\n","ev",{"x()":"DEATH"},"pop","/ev","\n","end",null],"s12_hide_1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:crates","/#","#","^IMAGE:bg_crates","/#","^Kau melompat ke balik tumpukan peti kayu di sudut paling gelap ruangan. Kayunya kasar dan lembap di punggungmu saat tubuhmu menekan dinding yang dingin seperti es, meringkuk sekecil mungkin di antara bayangan-bayangan yang menumpuk.","\n","^Kau menahan napas. Bau busuk yang manis dan menusuk, bercampur dengan bau tajam bahan kimia, menyapu melewatimu saat salah satu dari mereka melintas — begitu dekat hingga kau bisa mendengar bunyi basah setiap langkahnya dan merasakan getarannya merambat melalui lantai ke tulang-tulangmu.","\n","^Waktu berjalan dengan lambat yang menyiksa, setiap detik meregang seperti karet. Lalu sesuatu yang cepat dan BESAR melintas tepat di depanmu — bayangan raksasa yang nyaris tak terlihat — dan menghilang masuk ke dalam lorong. Kau tidak berani bernapas sampai suaranya benar-benar hilang ditelan kegelapan.","\n",{"->":"s12_hide_2"},null],"s12_hide_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:crates","/#","#","^IMAGE:bg_crates","/#","^Kau meringkuk di balik peti, lutut ditarik rapat ke dada. Napasmu tertahan di tenggorokan — setiap tarikan terasa seperti pengkhianatan terhadap dirimu sendiri. Di luar sana, aula masih bergolak dengan suara-suara yang tidak ingin kau kenali, dan yang bisa kau lakukan hanyalah menunggu.","\n","ev","str","^Tahan napas. Jangan bergerak sama sekali.","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Mengintip lewat celah peti","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Bersiap lari jika ketahuan","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"s12_hide_ok"},"\n",null],"c-1":["^ ",{"->":"s12_peek"},"\n",null],"c-2":["^ ",{"->":"s12_ready"},"\n",null]}],null],"s12_peek":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:crates","/#","#","^IMAGE:bg_crates","/#","#","^SFX:whisper","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Dari celah sempit di antara peti-peti itu, dunia terpotong menjadi serpihan gelap — dan kemudian kakinya muncul. Bukan kaki manusia. Sesuatu yang terlalu panjang, dengan terlalu banyak sendi, melintas perlahan dari kiri ke kanan disertai bunyi seret yang membuat bulu kudukmu berdiri. Bersamaan dengan itu, bau busuk menusuk hidungmu — amis, lembap, seperti daging yang sudah lama membusuk di ruangan tanpa udara.","\n","^Lalu — satu pasang kaki berhenti. Tepat di depan celahmu. Sekarang kau bisa melihatnya: matanya, kuning redup, menatap lurus ke dalam celah sempit tempat kau meringkuk. Duniamu berhenti. Tidak ada suara. Tidak ada napas. Hanya tatapan itu, menusuk, seolah ia bisa melihat ketakutanmu berdenyut di tenggorokan.","\n","^Lalu ia pergi. Begitu saja — berbalik dengan acuh, seolah kau hanyalah bayangan yang tidak layak dikejar. Lututmu hampir lemas, dadamu meledak dengan napas yang baru berani kau ambil. Lega membanjirimu — dan bersamaan dengan itu, rasa takut yang justru lebih tajam. Karena tadi, ia hampir melihatmu.","\n",{"->":"s12_hide_2"},null],"s12_ready":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:crates","/#","#","^IMAGE:bg_crates","/#","^Setiap otot di tubuhmu menegang seperti tali busur yang ditarik sampai batasnya. Matamu memetakan rute dengan cepat: dari peti ini ke pintu seberang, zig-zag di antara pilar-pilar tinggi itu, memanfaatkan setiap bayangan. Tidak ada ruang untuk ragu. Satu langkah salah, dan malam ini berakhir.","\n","^Kau mengatur napas — masuk perlahan lewat hidung, keluar lewat mulut yang hampir tak bersuara. Keringat dingin merambat di pelipismu, lengket dan menusuk dingin. Tubuhmu condong ke depan, siap melesat kapan pun. Tinggal menunggu momen yang tepat.","\n",{"->":"s12_ready_2"},null],"s12_ready_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:crates","/#","#","^IMAGE:bg_crates","/#","^Mereka masih sibuk sendiri — berpindah-pindah di antara peti, mengendus, tanpa menyadari kehadiranmu. Dan di seberang sana, pintu itu terlihat. Terbuka. Gelap. Menjanjikan sesuatu yang lebih baik daripada tempat ini. Detik ini adalah celahmu.","\n","ev","str","^Tetap bersembunyi","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Lari sekarang!","/str","/ev",{"*":".^.c-1","flg":4},{"c-0":["^ ",{"->":"s12_hide_ok"},"\n",null],"c-1":["^ ",{"->":"s12_run_1"},"\n",null]}],null],"s12_hide_ok":["#","^KICKER:Part 1 : Awal Mula","/#","#","^TAG:[Canon]","/#","#","^AUDIO:crates","/#","#","^IMAGE:bg_crates","/#","ev","str","^Ketakutan","/str",3,{"x()":"ADD_TEMP","exArgs":2},"pop","/ev","\n","^Kau tidak bergerak. Kau bahkan tidak bernapas. Tubuhmu merapat ke peti, menjadi satu dengan kegelapan — dingin, diam, tak berwujud. Hanya jantungmu yang berdebar, dan kau berdoa suaranya tidak keluar dari dadamu.","\n","^Satu per satu, mereka menjauh — terpancing oleh suara yang entah datang dari mana, langkah-langkah aneh itu menyeret pergi ke sudut aula yang lain. Perlahan, aula itu kembali 'tenang'. Tenang yang palsu, tenang yang bisa pecah kapan saja, tapi tenang.","\n","^Kau berhasil tak terdeteksi. Tapi ketakutan itu tidak ikut pergi. Ia menempel di kulitmu, di napasmu, di setiap bayangan yang bergerak — setidaknya untuk sementara, kau tidak akan bisa melupakannya.","\n",{"->":"s12_bridge"},null],"s12_run_1":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Kau melesat! Napas dalam membakar paru-parumu, kakimu menghantam lantai dengan bunyi gedebuk yang terdengar terlalu keras di aula yang sunyi. Beberapa pasang mata menoleh ke arahmu — lalu berpaling, acuh. Mereka tidak peduli. Belum.","\n","^Setengah jalan. Pintu seberang semakin dekat — kau hampir bisa merasakan udara gelap di baliknya. Lalu, dari sudut matamu: gerakan cepat dari samping! Terlalu cepat untuk sesuatu sebesar itu.","\n","^Makhluk kecil gesit itu berbelok tak terduga — bukan menjauh, melainkan ke arahmu! Kaki-kakinya yang ramping melesat di atas lantai, matanya terkunci padamu. Ia datang.","\n",{"->":"s12_run_2"},null],"s12_run_2":[["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Ia datang cepat — terlalu cepat. Pintu tinggal beberapa langkah lagi, dan kau bisa mendengar cakar-cakar kecil itu mencakar lantai di belakangmu. Pilihanmu sekarang menentukan segalanya.","\n","ev","str","^Zig-zag di antara mereka","/str","/ev",{"*":".^.c-0","flg":4},"ev","str","^Lari lurus secepat mungkin","/str","/ev",{"*":".^.c-1","flg":4},"ev","str","^Batalkan — kembali bersembunyi","/str","/ev",{"*":".^.c-2","flg":4},{"c-0":["^ ",{"->":"s12_run_ok"},"\n",null],"c-1":["^ ",{"->":"s12_run_straight"},"\n",null],"c-2":["^ ",{"->":"s12_hide_1"},"\n",null]}],null],"s12_run_straight":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","ev","str","^Takut","/str",1,{"x()":"ADD_EMOTION","exArgs":2},"pop","/ev","\n","^Kau lari lurus, secepat kaki bisa membawa. Dunia menyempit menjadi satu garis tunggal — pintu, pintu, pintu. Tidak ada lagi pilar, tidak ada lagi bayangan, hanya tujuan dan deru napasmu sendiri.","\n","^Cakar menyambar dari samping — kau menghindar tipis, tubuhmu miring dalam sepersekian detik. Udara tersayat di dekat pipimu. Terlalu dekat. Terlalu dekat. Tapi kakimu tidak berhenti.","\n",{"->":"s12_run_ok"},null],"s12_run_ok":["#","^KICKER:Part 1 : Awal Mula","/#","#","^TAG:[Terluka]","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","ev","str","^wounded","/str",{"x()":"SET_STATUS","exArgs":1},"pop","/ev","\n","ev","str","^Kaki Kiri Terluka","/str",{"x()":"SET_BODY","exArgs":1},"pop","/ev","\n","^Kau mencapai pintu — tapi di detik terakhir, cakarnya menyerempet kakimu. Panas menyengat meledak di kaki kirimu. Kau jatuh tersungkur melewati ambang pintu, dan ketika kau menoleh, luka robek menganga di kaki kirimu, darah merembes gelap ke kain celanamu.","\n","^Rasa sakit menyelimuti seluruh kakimu, berdenyut mengikuti detak jantungmu. Kau berhasil lewat — tapi dengan harga. Setiap langkah kini mengingatkanmu pada makhluk kecil itu.","\n","^Untuk sementara, kau tidak bisa berlari cepat. Kaki kirimu tidak akan mengizinkannya — dan Kegelapan tidak menunggu orang yang pincang.","\n",{"->":"s12_bridge"},null],"s12_bridge":["#","^KICKER:Part 1 : Awal Mula","/#","#","^AUDIO:hall","/#","#","^IMAGE:bg_hall","/#","^Aula parade mimpi buruk itu tertinggal di belakangmu, suaranya memudar menjadi dengung samar. Lorong di depan sunyi — terlalu sunyi, seolah tempat ini menahan napas bersamamu.","\n","^Kakimu melangkah — atau terpincang — maju di atas lantai yang dingin. Di dalam tasmu, catatan eksperimen itu terasa berat, seolah kertas-kertas itu menyimpan sesuatu yang tidak ingin kau ketahui.","\n","^Sesuatu menunggumu di depan. Kau bisa merasakannya di udara yang semakin dingin, di kegelapan yang semakin pekat. Cerita ini belum selesai.","\n",{"->":"tbc"},null],"tbc":["#","^AUDIO:corridor","/#","#","^IMAGE:bg_corridor","/#","^Bersambung…","\n","end",null],"global decl":["ev",false,{"VAR=":"f_d1"},false,{"VAR=":"f_d2"},false,{"VAR=":"f_d2c1"},false,{"VAR=":"f_d2c2"},false,{"VAR=":"f_d2c3"},false,{"VAR=":"f_d3"},false,{"VAR=":"f_d4"},false,{"VAR=":"f_rec_coin"},false,{"VAR=":"f_rec_desk"},false,{"VAR=":"f_rec_left"},false,{"VAR=":"f_rec_photos"},false,{"VAR=":"f_rec_read"},"/ev","end",null]}],"listDefs":{}};
